1	import React, { useEffect, useState } from 'react';
2	import { supabase } from '@/integrations/supabase/client';
3	import { Button } from '@/shared/ui/button';
4	import { Input } from '@/shared/ui/input';
5	import { Label } from '@/shared/ui/label';
6	import { Card, CardContent } from '@/shared/ui/card';
7	import { Badge } from '@/shared/ui/badge';
8	import {
9	  Plus,
10	  Trash2,
11	  DollarSign,
12	  TrendingUp,
13	  TrendingDown,
14	  FileText,
15	  Calendar,
16	} from 'lucide-react';
17	import { toast } from '@/shared/hooks/use-toast';
18	import {
19	  Dialog,
20	  DialogContent,
21	  DialogHeader,
22	  DialogTitle,
23	  DialogDescription,
24	} from '@/shared/ui/dialog';
25	import {
26	  Select,
27	  SelectContent,
