31	} from '@/shared/ui/select';
32	import { cn } from '@/shared/lib/utils';
33	import { wideInfo, wideError } from '@/shared/lib/telemetry/wide-events';
34	import { enrichWideEvent } from '@/shared/lib/telemetry/enrichWideEvent';
35	import { handleError } from '@/shared/lib/error-handler';
36	import { recordOperation, recordOperationDuration, recordError } from '@/shared/lib/telemetry/metrics';
37	import { withTrace } from '@/shared/lib/telemetry/tracer';
38	import { useTelemetryAttrs } from '@/shared/lib/telemetry/useTelemetryAttrs';
39	import { useFormTelemetry } from '@/shared/lib/telemetry/useFormTelemetry';
40	
41	interface Transacao {
42	  id: string;
43	  descricao: string;
44	  valor: number;
45	  tipo: 'receita' | 'despesa';
46	  categoria: string;
47	  data_transacao: string;
48	  comprovante_url: string | null;
49	}
