51	export function EventFinance({ eventoId }: { eventoId: string }) {
52	  const [transactions, setTransactions] = useState<Transacao[]>([]);
53	  const [loading, setLoading] = useState(true);
54	  const [isAddOpen, setIsAddOpen] = useState(false);
55	  const telemetryAttrs = useTelemetryAttrs();
56	  const { trackSubmissionStart, trackSubmissionSuccess, trackSubmissionError } = useFormTelemetry('evento_transacao');
57	
58	  // Form state
59	  const [form, setForm] = useState({
60	    descricao: '',
61	    valor: '',
62	    tipo: 'despesa' as 'receita' | 'despesa',
63	    categoria: 'outros',
64	    data_transacao: new Date().toISOString().split('T')[0],
65	  });
66	
67	  useEffect(() => {
68	    fetchTransactions();
69	    // eslint-disable-next-line react-hooks/exhaustive-deps
70	  }, [eventoId]);
71	
72	  const fetchTransactions = async () => {
73	    setLoading(true);
74	    await withTrace('gerencia.evento_financeiro.carregar', async () => {
75	      const startTime = performance.now();
76	      const { data, error } = await supabase
77	        .from('eventos_transacoes')
78	        .select('*')
79	        .eq('evento_id', eventoId)
80	        .order('data_transacao', { ascending: false });
81	
82	      if (error) {
83	        wideError('gerencia.evento_financeiro.erro', 'Erro ao carregar transações do evento', enrichWideEvent('eventos', {
84	          'error.message': error.message,
85	          'evento.id': eventoId,
86	          'evento.nome': 'financeiro',
87	          'evento.operacao': 'carregar_transacoes',
88	          'evento.tipo': 'financeiro',
89	        }));
90	        recordError('gerencia_evento_financeiro', 'carregar');
91	        handleError(error, { domain: 'eventos', operation: 'buscarTransacoes', showToast: false });
92	      } else {
93	        const results = data || [];
94	        setTransactions(results);
95	        const durationMs = Math.round(performance.now() - startTime);
96	        wideInfo('gerencia.evento_financeiro.carregado', 'Transações do evento carregadas', enrichWideEvent('eventos', {
97	          'evento.id': eventoId,
98	          'evento.operacao': 'carregar_transacoes',
99	          result_count: results.length,
100	          duration_ms: durationMs,
101	        }));
102	      }
103	    }, telemetryAttrs);
104	    setLoading(false);
105	  };
106	
107	  const handleAddTransaction = async () => {
108	    if (!form.descricao || !form.valor) {
109	      toast({ title: 'Preencha descrição e valor', variant: 'destructive' });
110	      return;
111	    }
112	
113	    trackSubmissionStart();
114	    const startTime = performance.now();
115	    try {
116	      await withTrace('gerencia.evento_transacao.registrar', async () => {
117	        const { error } = await supabase.from('eventos_transacoes').insert([
118	          {
119	            evento_id: eventoId,
120	            descricao: form.descricao,
121	            valor: parseFloat(form.valor),
122	            tipo: form.tipo,
123	            categoria: form.categoria,
124	            data_transacao: form.data_transacao,
125	          },
126	        ]);
127	
128	        if (error) throw error;
129	      }, telemetryAttrs);
130	
131	      const durationMs = Math.round(performance.now() - startTime);
132	      wideInfo('gerencia.evento_transacao.registrada', 'Transação do evento registrada', enrichWideEvent('eventos', {
133	        'evento.id': eventoId,
134	        'transacao.tipo': form.tipo,
135	        'transacao.categoria': form.categoria,
136	        'transacao.valor': parseFloat(form.valor),
137	        duration_ms: durationMs,
138	      }));
139	      recordOperation('gerencia.evento_transacao');
140	      recordOperationDuration('gerencia.evento_transacao', durationMs);
141	      trackSubmissionSuccess({ 'transacao.tipo': form.tipo, 'transacao.valor': parseFloat(form.valor) });
142	
143	      toast({ title: 'Transação registrada' });
144	      setIsAddOpen(false);
145	      setForm({
146	        descricao: '',
147	        valor: '',
148	        tipo: 'despesa',
149	        categoria: 'outros',
150	        data_transacao: new Date().toISOString().split('T')[0],
151	      });
152	      fetchTransactions();
153	    } catch (error: any) {
154	      wideError('gerencia.evento_transacao.erro', 'Erro ao registrar transação do evento', enrichWideEvent('eventos', {
155	        'error.message': error?.message ?? String(error),
156	        'evento.id': eventoId,
157	        'evento.operacao': 'registrar_transacao',
158	        'evento.tipo': form.tipo,
159	        'evento.valor_total': parseFloat(form.valor) || 0,
160	      }));
161	      recordError('gerencia_evento_transacao', 'registrar');
162	      handleError(error, { domain: 'eventos', operation: 'registrarTransacao', showToast: false });
163	      trackSubmissionError(error);
164	      toast({
165	        title: 'Erro ao registrar',
166	        description: error.message,
167	        variant: 'destructive',
168	      });
169	    }
170	  };
171	
172	  const deleteTransaction = async (id: string) => {
173	    if (!confirm('Excluir esta transação?')) return;
174	    const startTime = performance.now();
175	    try {
176	      await withTrace('gerencia.evento_transacao.excluir', async () => {
177	        const { error } = await supabase
178	          .from('eventos_transacoes')
179	          .delete()
180	          .eq('id', id);
181	        if (error) throw error;
182	      }, telemetryAttrs);
183	
184	      const durationMs = Math.round(performance.now() - startTime);
185	      setTransactions(transactions.filter((t) => t.id !== id));
186	      wideInfo('gerencia.evento_transacao.excluida', 'Transação do evento excluída', enrichWideEvent('eventos', {
187	        'evento.id': eventoId,
188	        'transacao.id': id,
189	        'evento.operacao': 'excluir_transacao',
190	        duration_ms: durationMs,
191	      }));
192	      recordOperation('gerencia.evento_transacao.excluir');
193	      recordOperationDuration('gerencia.evento_transacao.excluir', durationMs);
194	      toast({ title: 'Transação removida' });
195	    } catch (error: any) {
196	      wideError('gerencia.evento_transacao.erro', 'Erro ao excluir transação do evento', enrichWideEvent('eventos', {
197	        'error.message': error?.message ?? String(error),
198	        'evento.id': eventoId,
199	        'transacao.id': id,
200	        'evento.operacao': 'excluir_transacao',
201	      }));
202	      recordError('gerencia_evento_transacao', 'excluir');
203	      handleError(error, { domain: 'eventos', operation: 'excluirTransacao', showToast: false });
204	      toast({
205	        title: 'Erro ao remover',
206	        description: error.message,
207	        variant: 'destructive',
208	      });
209	    }
210	  };
211	
212	  const totalReceita = transactions
213	    .filter((t) => t.tipo === 'receita')
214	    .reduce((acc, t) => acc + t.valor, 0);
215	  const totalDespesa = transactions
216	    .filter((t) => t.tipo === 'despesa')
217	    .reduce((acc, t) => acc + t.valor, 0);
218	  const saldo = totalReceita - totalDespesa;
219	
220	  return (
221	    <div className="space-y-6">
222	      {/* Summary Cards */}
223	      <div className="grid grid-cols-3 gap-4">
224	        <Card className="border-none shadow-sm bg-green-50 dark:bg-green-900/20">
225	          <CardContent className="p-4">
226	            <div className="text-xs text-green-600 dark:text-green-400 font-medium uppercase tracking-wider mb-1">
227	              Receita
228	            </div>
229	            <div className="text-lg font-bold text-green-700 dark:text-green-300">
230	              R${' '}
231	              {totalReceita.toLocaleString('pt-BR', {
232	                minimumFractionDigits: 2,
233	              })}
234	            </div>
235	          </CardContent>
236	        </Card>
237	        <Card className="border-none shadow-sm bg-red-50 dark:bg-red-900/20">
238	          <CardContent className="p-4">
239	            <div className="text-xs text-red-600 dark:text-red-400 font-medium uppercase tracking-wider mb-1">
240	              Despesa
241	            </div>
242	            <div className="text-lg font-bold text-red-700 dark:text-red-300">
243	              R${' '}
244	              {totalDespesa.toLocaleString('pt-BR', {
245	                minimumFractionDigits: 2,
246	              })}
247	            </div>
248	          </CardContent>
249	        </Card>
250	        <Card
251	          className={cn(
252	            'border-none shadow-sm',
253	            saldo >= 0
254	              ? 'bg-blue-50 dark:bg-blue-900/20'
255	              : 'bg-orange-50 dark:bg-orange-900/20',
256	          )}
257	        >
258	          <CardContent className="p-4">
259	            <div
260	              className={cn(
261	                'text-xs font-medium uppercase tracking-wider mb-1',
262	                saldo >= 0
263	                  ? 'text-blue-600 dark:text-blue-400'
264	                  : 'text-orange-600 dark:text-orange-400',
265	              )}
266	            >
267	              Saldo
268	            </div>
269	            <div
270	              className={cn(
271	                'text-lg font-bold',
272	                saldo >= 0
273	                  ? 'text-blue-700 dark:text-blue-300'
274	                  : 'text-orange-700 dark:text-orange-300',
275	              )}
276	            >
277	              R$ {saldo.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
278	            </div>
279	          </CardContent>
280	        </Card>
281	      </div>
282	
283	      <div className="flex justify-between items-center">
284	        <h3 className="text-lg font-semibold text-[#2D362E] dark:text-white">
285	          Livro Caixa
286	        </h3>
287	        <Button
288	          data-mia-action="nova-transacao"
289	          onClick={() => setIsAddOpen(true)}
290	          size="sm"
291	          className="bg-[#57715B] hover:bg-[#4A614D]"
292	        >
293	          <Plus className="h-4 w-4 mr-2" /> Nova Transação
294	        </Button>
295	      </div>
296	
297	      {loading ? (
298	        <div className="text-center py-8 text-muted-foreground">
299	          Carregando transações...
300	        </div>
301	      ) : transactions.length === 0 ? (
302	        <div className="text-center py-12 border-2 border-dashed rounded-xl bg-white/50 dark:bg-white/5">
303	          <DollarSign className="h-10 w-10 mx-auto mb-2 text-muted-foreground opacity-50" />
304	          <p className="text-muted-foreground">Nenhuma transação registrada.</p>
