414	            <div className="space-y-2">
415	              <Label>Descrição</Label>
416	              <Input
417	                data-mia-field="descricao"
418	                value={form.descricao}
419	                onChange={(e) =>
420	                  setForm({ ...form, descricao: e.target.value })
421	                }
422	                placeholder="Ex: Pagamento de sinal"
423	              />
424	            </div>
425	
426	            <div className="grid grid-cols-2 gap-4">
427	              <div className="space-y-2">
428	                <Label>Valor (R$)</Label>
429	                <Input
430	                  data-mia-field="valor"
431	                  type="number"
432	                  value={form.valor}
433	                  onChange={(e) => setForm({ ...form, valor: e.target.value })}
434	                  placeholder="0.00"
435	                />
436	              </div>
437	              <div className="space-y-2">
438	                <Label>Categoria</Label>
439	                <Select
440	                  value={form.categoria}
441	                  onValueChange={(v) => setForm({ ...form, categoria: v })}
442	                >
443	                  <SelectTrigger data-mia-filter="categoria_transacao">
444	                    <SelectValue />
445	                  </SelectTrigger>
446	                  <SelectContent>
447	                    <SelectItem value="fixo">Custo Fixo</SelectItem>
448	                    <SelectItem value="variavel">Custo Variável</SelectItem>
449	                    <SelectItem value="pessoal">Pessoal</SelectItem>
450	                    <SelectItem value="transporte">Transporte</SelectItem>
451	                    <SelectItem value="alimentacao">Alimentação</SelectItem>
452	                    <SelectItem value="venda_produtos">
453	                      Venda de Produtos
454	                    </SelectItem>
455	                    <SelectItem value="servico">Serviço</SelectItem>
456	                    <SelectItem value="outros">Outros</SelectItem>
457	                  </SelectContent>
458	                </Select>
459	              </div>
460	            </div>
