import React, { useEffect, useState } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import { Label } from '@/shared/ui/label';
import { Card, CardContent } from '@/shared/ui/card';
import { Badge } from '@/shared/ui/badge';
import {
  Plus,
  Trash2,
  DollarSign,
  TrendingUp,
  TrendingDown,
  FileText,
  Calendar,
} from 'lucide-react';
import { toast } from '@/shared/hooks/use-toast';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/shared/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/shared/ui/select';
import { cn } from '@/shared/lib/utils';
import { wideInfo, wideError } from '@/shared/lib/telemetry/wide-events';
import { enrichWideEvent } from '@/shared/lib/telemetry/enrichWideEvent';
import { handleError } from '@/shared/lib/error-handler';
import { recordOperation, recordOperationDuration, recordError } from '@/shared/lib/telemetry/metrics';
import { withTrace } from '@/shared/lib/telemetry/tracer';
import { useTelemetryAttrs } from '@/shared/lib/telemetry/useTelemetryAttrs';
import { useFormTelemetry } from '@/shared/lib/telemetry/useFormTelemetry';

interface Transacao {
  id: string;
  descricao: string;
  valor: number;
  tipo: 'receita' | 'despesa';
  categoria: string;
  data_transacao: string;
  comprovante_url: string | null;
}

export function EventFinance({ eventoId }: { eventoId: string }) {
  const [transactions, setTransactions] = useState<Transacao[]>([]);
  const [loading, setLoading] = useState(true);
  const [isAddOpen, setIsAddOpen] = useState(false);
  const telemetryAttrs = useTelemetryAttrs();
  const { trackSubmissionStart, trackSubmissionSuccess, trackSubmissionError } = useFormTelemetry('evento_transacao');

  // Form state
  const [form, setForm] = useState({
    descricao: '',
    valor: '',
    tipo: 'despesa' as 'receita' | 'despesa',
    categoria: 'outros',
    data_transacao: new Date().toISOString().split('T')[0],
  });

  useEffect(() => {
    fetchTransactions();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [eventoId]);

  const fetchTransactions = async () => {
    setLoading(true);
    await withTrace('gerencia.evento_financeiro.carregar', async () => {
      const startTime = performance.now();
      const { data, error } = await supabase
        .from('eventos_transacoes')
        .select('*')
        .eq('evento_id', eventoId)
        .order('data_transacao', { ascending: false });

      if (error) {
        wideError('gerencia.evento_financeiro.erro', 'Erro ao carregar transações do evento', enrichWideEvent('eventos', {
          'error.message': error.message,
          'evento.id': eventoId,
          'evento.nome': 'financeiro',
          'evento.operacao': 'carregar_transacoes',
          'evento.tipo': 'financeiro',
        }));
        recordError('gerencia_evento_financeiro', 'carregar');
        handleError(error, { domain: 'eventos', operation: 'buscarTransacoes', showToast: false });
      } else {
        const results = data || [];
        setTransactions(results);
        const durationMs = Math.round(performance.now() - startTime);
        wideInfo('gerencia.evento_financeiro.carregado', 'Transações do evento carregadas', enrichWideEvent('eventos', {
          'evento.id': eventoId,
          'evento.operacao': 'carregar_transacoes',
          result_count: results.length,
          duration_ms: durationMs,
        }));
      }
    }, telemetryAttrs);
    setLoading(false);
  };

  const handleAddTransaction = async () => {
    if (!form.descricao || !form.valor) {
      toast({ title: 'Preencha descrição e valor', variant: 'destructive' });
      return;
    }

    trackSubmissionStart();
    const startTime = performance.now();
    try {
      await withTrace('gerencia.evento_transacao.registrar', async () => {
        const { error } = await supabase.from('eventos_transacoes').insert([
          {
            evento_id: eventoId,
            descricao: form.descricao,
            valor: parseFloat(form.valor),
            tipo: form.tipo,
            categoria: form.categoria,
            data_transacao: form.data_transacao,
          },
        ]);

        if (error) throw error;
      }, telemetryAttrs);

      const durationMs = Math.round(performance.now() - startTime);
      wideInfo('gerencia.evento_transacao.registrada', 'Transação do evento registrada', enrichWideEvent('eventos', {
        'evento.id': eventoId,
        'transacao.tipo': form.tipo,
        'transacao.categoria': form.categoria,
        'transacao.valor': parseFloat(form.valor),
        duration_ms: durationMs,
      }));
      recordOperation('gerencia.evento_transacao');
      recordOperationDuration('gerencia.evento_transacao', durationMs);
      trackSubmissionSuccess({ 'transacao.tipo': form.tipo, 'transacao.valor': parseFloat(form.valor) });

      toast({ title: 'Transação registrada' });
      setIsAddOpen(false);
      setForm({
        descricao: '',
        valor: '',
        tipo: 'despesa',
        categoria: 'outros',
        data_transacao: new Date().toISOString().split('T')[0],
      });
      fetchTransactions();
    } catch (error: any) {
      wideError('gerencia.evento_transacao.erro', 'Erro ao registrar transação do evento', enrichWideEvent('eventos', {
        'error.message': error?.message ?? String(error),
        'evento.id': eventoId,
        'evento.operacao': 'registrar_transacao',
        'evento.tipo': form.tipo,
        'evento.valor_total': parseFloat(form.valor) || 0,
      }));
      recordError('gerencia_evento_transacao', 'registrar');
      handleError(error, { domain: 'eventos', operation: 'registrarTransacao', showToast: false });
      trackSubmissionError(error);
      toast({
        title: 'Erro ao registrar',
        description: error.message,
        variant: 'destructive',
      });
    }
  };

  const deleteTransaction = async (id: string) => {
    if (!confirm('Excluir esta transação?')) return;
    const startTime = performance.now();
    try {
      await withTrace('gerencia.evento_transacao.excluir', async () => {
        const { error } = await supabase
          .from('eventos_transacoes')
          .delete()
          .eq('id', id);
        if (error) throw error;
      }, telemetryAttrs);

      const durationMs = Math.round(performance.now() - startTime);
      setTransactions(transactions.filter((t) => t.id !== id));
      wideInfo('gerencia.evento_transacao.excluida', 'Transação do evento excluída', enrichWideEvent('eventos', {
        'evento.id': eventoId,
        'transacao.id': id,
        'evento.operacao': 'excluir_transacao',
        duration_ms: durationMs,
      }));
      recordOperation('gerencia.evento_transacao.excluir');
      recordOperationDuration('gerencia.evento_transacao.excluir', durationMs);
      toast({ title: 'Transação removida' });
    } catch (error: any) {
      wideError('gerencia.evento_transacao.erro', 'Erro ao excluir transação do evento', enrichWideEvent('eventos', {
        'error.message': error?.message ?? String(error),
        'evento.id': eventoId,
        'transacao.id': id,
        'evento.operacao': 'excluir_transacao',
      }));
      recordError('gerencia_evento_transacao', 'excluir');
      handleError(error, { domain: 'eventos', operation: 'excluirTransacao', showToast: false });
      toast({
        title: 'Erro ao remover',
        description: error.message,
        variant: 'destructive',
      });
    }
  };

  const totalReceita = transactions
    .filter((t) => t.tipo === 'receita')
    .reduce((acc, t) => acc + t.valor, 0);
  const totalDespesa = transactions
    .filter((t) => t.tipo === 'despesa')
    .reduce((acc, t) => acc + t.valor, 0);
  const saldo = totalReceita - totalDespesa;

  return (
    <div className="space-y-6">
      {/* Summary Cards */}
      <div className="grid grid-cols-3 gap-4">
        <Card className="border-none shadow-sm bg-green-50 dark:bg-green-900/20">
          <CardContent className="p-4">
            <div className="text-xs text-green-600 dark:text-green-400 font-medium uppercase tracking-wider mb-1">
              Receita
            </div>
            <div className="text-lg font-bold text-green-700 dark:text-green-300">
              R${' '}
              {totalReceita.toLocaleString('pt-BR', {
                minimumFractionDigits: 2,
              })}
            </div>
          </CardContent>
        </Card>
        <Card className="border-none shadow-sm bg-red-50 dark:bg-red-900/20">
          <CardContent className="p-4">
            <div className="text-xs text-red-600 dark:text-red-400 font-medium uppercase tracking-wider mb-1">
              Despesa
            </div>
            <div className="text-lg font-bold text-red-700 dark:text-red-300">
              R${' '}
              {totalDespesa.toLocaleString('pt-BR', {
                minimumFractionDigits: 2,
              })}
            </div>
          </CardContent>
        </Card>
        <Card
          className={cn(
            'border-none shadow-sm',
            saldo >= 0
              ? 'bg-blue-50 dark:bg-blue-900/20'
              : 'bg-orange-50 dark:bg-orange-900/20',
          )}
        >
          <CardContent className="p-4">
            <div
              className={cn(
                'text-xs font-medium uppercase tracking-wider mb-1',
                saldo >= 0
                  ? 'text-blue-600 dark:text-blue-400'
                  : 'text-orange-600 dark:text-orange-400',
              )}
            >
              Saldo
            </div>
            <div
              className={cn(
                'text-lg font-bold',
                saldo >= 0
                  ? 'text-blue-700 dark:text-blue-300'
                  : 'text-orange-700 dark:text-orange-300',
              )}
            >
              R$ {saldo.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
            </div>
          </CardContent>
        </Card>
      </div>

      <div className="flex justify-between items-center">
        <h3 className="text-lg font-semibold text-[#2D362E] dark:text-white">
          Livro Caixa
        </h3>
        <Button
          data-mia-action="nova-transacao"
          onClick={() => setIsAddOpen(true)}
          size="sm"
          className="bg-[#57715B] hover:bg-[#4A614D]"
        >
          <Plus className="h-4 w-4 mr-2" /> Nova Transação
        </Button>
      </div>

      {loading ? (
        <div className="text-center py-8 text-muted-foreground">
          Carregando transações...
        </div>
      ) : transactions.length === 0 ? (
        <div className="text-center py-12 border-2 border-dashed rounded-xl bg-white/50 dark:bg-white/5">
          <DollarSign className="h-10 w-10 mx-auto mb-2 text-muted-foreground opacity-50" />
          <p className="text-muted-foreground">Nenhuma transação registrada.</p>
        </div>
      ) : (
        <div className="space-y-3">
          {transactions.map((t) => (
            <div
              key={t.id}
              className="flex items-center justify-between p-4 bg-white dark:bg-[#1A1A1A] rounded-xl shadow-sm border border-transparent hover:border-[#E6DCCF] dark:hover:border-white/10 transition-all"
            >
              <div className="flex items-center gap-4">
                <div
                  className={cn(
                    'h-10 w-10 rounded-full flex items-center justify-center',
                    t.tipo === 'receita'
                      ? 'bg-green-100 text-green-600'
                      : 'bg-red-100 text-red-600',
                  )}
                >
                  {t.tipo === 'receita' ? (
                    <TrendingUp className="h-5 w-5" />
                  ) : (
                    <TrendingDown className="h-5 w-5" />
                  )}
                </div>
                <div>
                  <div className="font-medium text-[#2D362E] dark:text-white">
                    {t.descricao}
                  </div>
                  <div className="flex items-center text-xs text-muted-foreground gap-2">
                    <span className="flex items-center">
                      <Calendar className="h-3 w-3 mr-1" />{' '}
                      {new Date(t.data_transacao).toLocaleDateString()}
                    </span>
                    <Badge
                      variant="secondary"
                      className="text-[10px] h-5 px-1.5"
                    >
                      {t.categoria}
                    </Badge>
                  </div>
                </div>
              </div>
              <div className="flex items-center gap-4">
                <div
                  className={cn(
                    'font-bold',
                    t.tipo === 'receita' ? 'text-green-600' : 'text-red-600',
                  )}
                >
                  {t.tipo === 'receita' ? '+' : '-'} R${' '}
                  {t.valor.toLocaleString('pt-BR', {
                    minimumFractionDigits: 2,
                  })}
                </div>
                <Button
                  data-mia-action="excluir-transacao"
                  data-mia-transacao-id={t.id}
                  variant="ghost"
                  size="icon"
                  className="h-8 w-8 text-muted-foreground hover:text-red-500"
                  onClick={() => deleteTransaction(t.id)}
                >
                  <Trash2 className="h-4 w-4" />
                </Button>
              </div>
            </div>
          ))}
        </div>
      )}

      <Dialog open={isAddOpen} onOpenChange={setIsAddOpen}>
        <DialogContent data-mia-modal="nova-transa-o">
          <DialogHeader>
            <DialogTitle>Nova Transação</DialogTitle>
            <DialogDescription>
              Registre uma entrada ou saída financeira para este evento.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Tipo</Label>
                <Select
                  value={form.tipo}
                  onValueChange={(v: 'receita' | 'despesa') =>
                    setForm({ ...form, tipo: v })
                  }
                >
                  <SelectTrigger data-mia-filter="tipo_transacao">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="receita">Receita (Entrada)</SelectItem>
                    <SelectItem value="despesa">Despesa (Saída)</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label>Data</Label>
                <Input
                  data-mia-field="data_transacao"
                  type="date"
                  value={form.data_transacao}
                  onChange={(e) =>
                    setForm({ ...form, data_transacao: e.target.value })
                  }
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label>Descrição</Label>
              <Input
                data-mia-field="descricao"
                value={form.descricao}
                onChange={(e) =>
                  setForm({ ...form, descricao: e.target.value })
                }
                placeholder="Ex: Pagamento de sinal"
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Valor (R$)</Label>
                <Input
                  data-mia-field="valor"
                  type="number"
                  value={form.valor}
                  onChange={(e) => setForm({ ...form, valor: e.target.value })}
                  placeholder="0.00"
                />
              </div>
              <div className="space-y-2">
                <Label>Categoria</Label>
                <Select
                  value={form.categoria}
                  onValueChange={(v) => setForm({ ...form, categoria: v })}
                >
                  <SelectTrigger data-mia-filter="categoria_transacao">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="fixo">Custo Fixo</SelectItem>
                    <SelectItem value="variavel">Custo Variável</SelectItem>
                    <SelectItem value="pessoal">Pessoal</SelectItem>
                    <SelectItem value="transporte">Transporte</SelectItem>
                    <SelectItem value="alimentacao">Alimentação</SelectItem>
                    <SelectItem value="venda_produtos">
                      Venda de Produtos
                    </SelectItem>
                    <SelectItem value="servico">Serviço</SelectItem>
                    <SelectItem value="outros">Outros</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>

            <Button data-mia-action="add-transaction"
              onClick={handleAddTransaction}
              className={cn(
                'w-full',
                form.tipo === 'receita'
                  ? 'bg-green-600 hover:bg-green-700'
                  : 'bg-red-600 hover:bg-red-700',
              )}
            >
              Registrar {form.tipo === 'receita' ? 'Receita' : 'Despesa'}
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

