import { render, screen } from '@testing-library/react';
import { describe, it, expect, vi } from 'vitest';

// ── Mocks ──────────────────────────────────────────────────────────────────
vi.mock('@/integrations/supabase/client', () => ({
  supabase: {
    from: () => ({
      select: () => ({
        eq: () => ({
          order: () => Promise.resolve({ data: [], error: null }),
        }),
      }),
      insert: () => Promise.resolve({ error: null }),
      delete: () => ({
        eq: () => Promise.resolve({ error: null }),
      }),
    }),
  },
}));

vi.mock('@/shared/hooks/use-toast', () => ({
  toast: vi.fn(),
}));

vi.mock('@/shared/lib/utils', () => ({
  cn: (...args: any[]) => args.filter(Boolean).join(' '),
}));

// ── Helper tests (pure logic) ──────────────────────────────────────────────

const calcSaldo = (transactions: { tipo: string; valor: number }[]) => {
  const totalReceita = transactions
    .filter((t) => t.tipo === 'receita')
    .reduce((acc, t) => acc + t.valor, 0);
  const totalDespesa = transactions
    .filter((t) => t.tipo === 'despesa')
    .reduce((acc, t) => acc + t.valor, 0);
  return totalReceita - totalDespesa;
};

describe('EventFinance — calcSaldo helper', () => {
  it('calculates saldo as receita minus despesa', () => {
    const transactions = [
      { tipo: 'receita', valor: 5000 },
      { tipo: 'despesa', valor: 2000 },
    ];
    expect(calcSaldo(transactions)).toBe(3000);
  });

  it('returns negative saldo when despesas exceed receitas', () => {
    const transactions = [
      { tipo: 'receita', valor: 1000 },
      { tipo: 'despesa', valor: 3000 },
    ];
    expect(calcSaldo(transactions)).toBe(-2000);
  });

  it('handles empty transactions', () => {
    expect(calcSaldo([])).toBe(0);
  });

  it('handles only receita', () => {
    const transactions = [{ tipo: 'receita', valor: 2500 }];
    expect(calcSaldo(transactions)).toBe(2500);
  });

  it('handles only despesa', () => {
